// wiki_read: recall/search only return previews; this returns the page body.
// "raw/"-prefixed ids read the immutable raw packet (windowed like wiki pages).
registerTool2("wiki_read", {
  description: "Read the full content of a wiki page (frontmatter + markdown body). wiki_recall/wiki_search only return short previews — pass the page ID they returned here to get the actual page; always answer from full page content, never from previews. A page_id starting with \"raw/\" reads the original source packet file instead (e.g. \"raw/sources/SRC-2026-09-23-014/extracted.md\", the raw_path found in a source page's frontmatter). Long pages are windowed via offset/limit. Conflict rule: when pages or sources disagree, prefer the one with the newer event time — a page's event time is the newest date among its \"## Evolution\" entries (entries start with an ISO date, YYYY-MM-DD), falling back to the SRC id date (SRC-YYYY-MM-DD) when the page has no Evolution section. Within a page, the body is the current conclusion and the \"## Evolution\" (or \"## 演进\") section is history; for point-in-time questions (\"what was X in September\"), answer from the Evolution entry whose date precedes that time, not the current body. On long pages the history section sits near the end — page through with offset to read it before answering history questions. Cite the page you relied on; quote provenance fields (origin_url/author) verbatim from the frontmatter — never reconstruct or shorten them.",
  inputSchema: object({
    page_id: string2().describe('Page ID as returned by wiki_recall/wiki_search (e.g. "concepts/强化学习"), or a raw packet path like "raw/sources/SRC-2026-09-24-001/extracted.md"'),
    offset: number2().optional().default(0).describe("Character offset to start reading from (default 0)"),
    limit: number2().optional().default(6000).describe("Max characters to return per call (default 6000, max 20000)")
  })
}, async ({ page_id, offset, limit }) => {
  if (!hasVault()) {
    return {
      content: [
        {
          type: "text",
          text: "No wiki vault found. Set WIKI_ROOT or run wiki_bootstrap first."
        }
      ],
      isError: true
    };
  }
  const id = String(page_id).trim().replace(/^\//, "");
  if (!id || id.includes("..") || id.includes("\0")) {
    return {
      content: [
        {
          type: "text",
          text: `Invalid page_id: ${page_id}`
        }
      ],
      isError: true
    };
  }
  const paths = getPaths();
  let pagePath;
  if (id.startsWith("raw/")) {
    pagePath = join24(paths.raw, id.slice(4));
  } else {
    const relNoExt = id.endsWith(".md") ? id.slice(0, -3) : id;
    pagePath = join24(paths.wiki, `${relNoExt}.md`);
  }
  if (!existsSync13(pagePath)) {
    return {
      content: [
        {
          type: "text",
          text: `Page not found: ${id}. Use wiki_search to find the exact page ID.`
        }
      ],
      isError: true
    };
  }
  const { readFile } = await import("node:fs/promises");
  const text = await readFile(pagePath, "utf-8");
  const off = Math.max(0, Math.floor(offset ?? 0));
  const lim = Math.min(2e4, Math.max(500, Math.floor(limit ?? 6e3)));
  const slice = text.slice(off, off + lim);
  const hasMore = off + slice.length < text.length;
  const header = `[wiki_read] page=${id} total_chars=${text.length} offset=${off} returned=${slice.length}${hasMore ? ` has_more=true (call again with offset=${off + slice.length})` : ""}`;
  return {
    content: [
      {
        type: "text",
        text: `${header}
\n${slice}`
      }
    ]
  };
});
